package com.cafeina.executor;
import static org.junit.Assert.*; import java.util.*; import org.junit.Test;
public final class AiMissionToolRunnerTest {
 private AiMissionToolRunner runner(InMemoryAiMissionStore s,List<String> calls){AiToolRegistry r=new AiToolRegistry();r.register(new AiTool(){public String name(){return "inspect";}public Set<String> requiredCapabilities(){return Collections.singleton("world.read");}public AiToolResult execute(AiToolRequest q){calls.add(q.projectId);return AiToolResult.success("ok");}});return new AiMissionToolRunner(s,new AiToolPlanRunner(new AiToolExecutor(r,new AiCapabilitySet(Collections.singleton("world.read")))),new AiToolExecutionPolicy(5));}
 @Test public void runningMissionCanExecuteSameProjectPlan(){InMemoryAiMissionStore s=new InMemoryAiMissionStore();s.save(new AiMissionRecord("m","p","g",AiMissionState.RUNNING,1));List<String> calls=new ArrayList<>();AiToolPlan p=new AiToolPlan(Collections.singletonList(new AiToolPlan.Step("inspect",new AiToolRequest("p",null))));assertEquals(1,runner(s,calls).run("m",p).size());assertEquals(Collections.singletonList("p"),calls);}
 @Test public void waitingMissionCannotExecute(){InMemoryAiMissionStore s=new InMemoryAiMissionStore();s.save(new AiMissionRecord("m","p","g",AiMissionState.WAITING_USER,1));List<String> calls=new ArrayList<>();AiToolPlan p=new AiToolPlan(Collections.singletonList(new AiToolPlan.Step("inspect",new AiToolRequest("p",null))));assertThrows(IllegalStateException.class,()->runner(s,calls).run("m",p));assertTrue(calls.isEmpty());}
 @Test public void crossProjectPlanCannotExecute(){InMemoryAiMissionStore s=new InMemoryAiMissionStore();s.save(new AiMissionRecord("m","p","g",AiMissionState.RUNNING,1));List<String> calls=new ArrayList<>();AiToolPlan p=new AiToolPlan(Collections.singletonList(new AiToolPlan.Step("inspect",new AiToolRequest("other",null))));assertThrows(SecurityException.class,()->runner(s,calls).run("m",p));assertTrue(calls.isEmpty());}
}
